def reader(name: String): Resource[IO, BufferedReader] =
  Resource.make(IO(new BufferedReader(new FileReader(name))))(r => IO(r.close()))

val count: IO[Long] =
  (reader("a.txt") |+| reader("b.txt")).use { (a, b) =>
    IO(a.lines().count() + b.lines().count())
  }          // both closed (b then a) even if the count or the caller fails
